-- Retour du 10/11/2026 : explications depliables (bouton « i » de l'ecran des parametres) des parametres crees depuis
-- janvier 2026 dont la valeur est 0 ou 1. Chaque explication a ete ecrite d'apres le code qui lit le parametre ;
-- format JSON {regle, titre, entetes, cas, rappels} (util.ExplicationParametre). Un parametre que plus aucun code ne
-- lit n'a pas d'explication : il est signale dans docs/notices/NOTICE_EXPLICATIONS_PARAMETRES.md.
-- Rejouable : une explication deja presente n'est pas ecrasee.

INSERT INTO parametre_explication (str_KEY, explication)
SELECT 'SEMOIS_ABC',
       '{"regle":"À 1, le calcul SEMOIS du seuil et de la quantité de réapprovisionnement utilise les réglages de la classe ABC de chaque produit (Q1, Q2, nombre de mois Q3, calcul à la semaine ou au jour). À 0, le calcul SEMOIS standard reste en place, avec les paramètres généraux Q1, Q2 et Q3 pour tous les produits. La valeur est relue à chaque calcul : le passage mensuel et le recalcul manuel des seuils. Ce paramètre n''a d''effet que si la gestion SEMOIS est active (SEMOIS à 1).","titre":"Calcul du seuil et de la quantité à commander","entetes":["Cas","Effet"],"cas":[["0","SEMOIS standard : mêmes Q1, Q2, Q3 pour tous les produits (4, 2 et 3 si non renseignés)."],["1, classe à la semaine","Consommation = ventes des Q3 derniers mois pleins / (Q3 x 4). Seuil = consommation x Q1, quantité = consommation x Q2, arrondis à l''entier supérieur."],["1, classe au jour","Consommation = ventes des Q3 derniers mois pleins / nombre de jours de ces mois. Même calcul du seuil et de la quantité."],["1, produit sans classe active","Le produit est calculé avec les paramètres généraux Q1, Q2, Q3, à la semaine."]],"rappels":["Exclusif avec le mode SEMOIS par produit (SEMOIS_PAR_PRODUIT) : mettre l''un à 1 remet l''autre à 0 à l''enregistrement.","Si les deux valaient 1 malgré tout, c''est le calcul par classe ABC qui s''applique.","Le détail du calcul, produit par produit, est écrit dans un fichier daté du dossier reappro_logs, sur le disque de données."]}'
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM parametre_explication WHERE str_KEY = 'SEMOIS_ABC');

INSERT INTO parametre_explication (str_KEY, explication)
SELECT 'ABC_AUTO_RECLASS',
       '{"regle":"À 1, le logiciel reclasse automatiquement les produits en classes A, B, C une fois par mois, d''après les quantités vendues sur toute la pharmacie. À 0, aucune reclassification automatique n''a lieu. Le contrôle passe chaque nuit à 2 h 30 sur le poste serveur et relit le paramètre à ce moment-là ; si le classement du mois est déjà fait, il ne refait rien. Si le paramètre est absent, il est considéré à 1.","titre":"Reclassification ABC mensuelle","entetes":["Valeur","Effet"],"cas":[["0","Les classes ABC des produits ne changent plus toutes seules."],["1","Une fois par mois, chaque produit reçoit la classe A, B ou C calculée sur les ventes des derniers mois (12 mois par défaut, réglable par le nombre de mois de la reclassification, ABC_RECLASS_NB_MOIS)."],["1, serveur éteint la nuit du 1er","Le classement est rattrapé au passage suivant, tant qu''il n''a pas été fait dans le mois."],["1, classement incomplet","Le mois n''est pas marqué comme fait : le logiciel recommence au passage suivant."]],"rappels":["Le résultat du dernier passage (date, nombre de produits, répartition A/B/C, statut) est noté dans le paramètre d''information de la dernière reclassification (ABC_LAST_RECLASS_INFO).","Ces classes servent au calcul des seuils quand le calcul SEMOIS par classe ABC est actif (SEMOIS_ABC à 1).","Le traitement ne tourne que sur le poste qui porte les tâches du serveur."]}'
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM parametre_explication WHERE str_KEY = 'ABC_AUTO_RECLASS');

INSERT INTO parametre_explication (str_KEY, explication)
SELECT 'SEMOIS_PAR_PRODUIT',
       '{"regle":"À 1, le calcul SEMOIS prend pour chaque produit le Q1 et le Q2 saisis sur sa fiche article ; la période de ventes reste celle du paramètre général Q3. À 0, le calcul SEMOIS standard s''applique, avec les mêmes Q1 et Q2 pour tous les produits. La valeur est relue à chaque calcul : le passage mensuel et le recalcul manuel des seuils. Ce paramètre n''a d''effet que si la gestion SEMOIS est active (SEMOIS à 1) et si le calcul par classe ABC est à l''arrêt (SEMOIS_ABC à 0).","titre":"Calcul du seuil et de la quantité à commander","entetes":["Cas","Effet"],"cas":[["0","SEMOIS standard : Q1, Q2, Q3 généraux pour tous les produits."],["1, Q1 et Q2 saisis sur la fiche","Consommation par semaine = ventes des Q3 derniers mois pleins / (Q3 x 4). Seuil = consommation x Q1 de la fiche, quantité = consommation x Q2 de la fiche, arrondis à l''entier supérieur."],["1, Q1 ou Q2 vide ou à 0 sur la fiche","La valeur manquante est remplacée par le paramètre général (4 pour Q1, 2 pour Q2 si non renseignés)."],["1, Q3 général à 0 ou absent","La période retenue est de 3 mois."]],"rappels":["Exclusif avec le calcul SEMOIS par classe ABC (SEMOIS_ABC) : mettre l''un à 1 remet l''autre à 0 à l''enregistrement.","Le détail du calcul est écrit dans un fichier daté du dossier reappro_logs, sur le disque de données."]}'
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM parametre_explication WHERE str_KEY = 'SEMOIS_PAR_PRODUIT');

INSERT INTO parametre_explication (str_KEY, explication)
SELECT 'KEY_SMS_AVOIR_IMMEDIAT',
       '{"regle":"À l''entrée en stock d''un bon de livraison, le logiciel prépare un message pour chaque client dont des produits en avoir viennent d''arriver. À 1, le SMS part tout de suite, dès que l''entrée en stock est validée. À 0 (ou paramètre absent), le message est seulement enregistré : il n''est pas envoyé à ce moment-là. La valeur est relue à chaque entrée en stock.","titre":"SMS « vos produits en avoir sont disponibles »","entetes":["Valeur","Effet"],"cas":[["0","Le message est créé pour le client, sans envoi immédiat."],["1","Le SMS est envoyé au client juste après la validation de l''entrée en stock."]],"rappels":["Le message cite les produits en avoir, leur quantité, la référence du ticket et le montant de la vente.","Seules les ventes rattachées à un client donnent lieu à un message."]}'
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM parametre_explication WHERE str_KEY = 'KEY_SMS_AVOIR_IMMEDIAT');

INSERT INTO parametre_explication (str_KEY, explication)
SELECT 'SUPPORT_NOTIFY_ENABLED',
       '{"regle":"À 1, chaque ticket créé automatiquement par le logiciel est aussi envoyé par e-mail à l''adresse du support (SUPPORT_EMAIL). À toute autre valeur, le ticket est créé sans e-mail. La valeur est relue à chaque ticket automatique.","titre":"E-mail au support pour un ticket automatique","entetes":["Cas","Effet"],"cas":[["0","Aucun e-mail. Le ticket reste visible dans le Centre de Support."],["1, adresse du support renseignée","Un e-mail part avec le numéro du ticket, le sujet, le module, la priorité et la description."],["1, adresse du support vide","Aucun e-mail ne part. Le contrôle du support le signale comme anomalie."],["1, compte d''envoi des e-mails non configuré","Aucun e-mail ne part."]],"rappels":["Dépend de l''adresse e-mail du support (SUPPORT_EMAIL) et du compte d''envoi des e-mails de l''officine.","Ne concerne que les tickets automatiques ; leur création dépend du paramètre de création automatique des tickets (SUPPORT_AUTO_TICKET_ENABLED)."]}'
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM parametre_explication WHERE str_KEY = 'SUPPORT_NOTIFY_ENABLED');

INSERT INTO parametre_explication (str_KEY, explication)
SELECT 'SUPPORT_MONITOR_ENABLED',
       '{"regle":"À 1, le logiciel contrôle toutes les 5 minutes la mémoire du serveur et l''espace libre sur le disque, et crée une alerte avant le blocage. Il vérifie aussi, une fois par heure, que les traitements planifiés ont bien tourné. À toute autre valeur, ces contrôles ne font rien. La valeur est relue à chaque passage.","titre":"Ce qui est surveillé à 1","entetes":["Contrôle","Alerte"],"cas":[["Mémoire du serveur","Alerte après 3 mesures de suite au-dessus du seuil de mémoire (85 % par défaut, SUPPORT_MEM_THRESHOLD_PCT)."],["Espace disque","Alerte si l''espace libre passe sous le minimum (1024 Mo par défaut, SUPPORT_DISK_MIN_MB), sur le disque du support et sur celui des journaux du serveur."],["Traitements planifiés","Alerte si le dernier passage d''un traitement suivi est introuvable ou trop ancien."]],"rappels":["Au plus une alerte par ressource et par jour.","Les alertes apparaissent dans le Centre de Support.","À 0, un disque presque plein ou une mémoire saturée ne sont plus signalés à l''avance."]}'
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM parametre_explication WHERE str_KEY = 'SUPPORT_MONITOR_ENABLED');

INSERT INTO parametre_explication (str_KEY, explication)
SELECT 'SUPPORT_SLOWLOG_ENABLED',
       '{"regle":"À 1, le logiciel mesure la durée des demandes faites par les écrans et enregistre un événement de performance pour chaque demande qui dépasse le seuil de lenteur (5 secondes par défaut, réglable en millisecondes, SUPPORT_SLOW_MS). À 0, aucune lenteur n''est enregistrée. Seule la valeur 0 désactive ; toute autre valeur, ou l''absence du paramètre, laisse la détection active. Le réglage est relu au plus une fois par minute, et seulement quand une demande lente se présente.","titre":"Détection des écrans lents","entetes":["Valeur","Effet"],"cas":[["0","Les lenteurs ne sont plus enregistrées."],["1","Chaque demande plus longue que le seuil est notée avec l''écran appelé, la durée, le seuil et l''utilisateur."]],"rappels":["Seuls les écrans qui passent par les nouveaux services sont mesurés ; les anciens écrans ne le sont pas.","Après un passage de 0 à 1, la détection ne reprend qu''au redémarrage du serveur.","Les lenteurs relevées sont visibles dans le Centre de Support, module Performance."]}'
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM parametre_explication WHERE str_KEY = 'SUPPORT_SLOWLOG_ENABLED');

INSERT INTO parametre_explication (str_KEY, explication)
SELECT 'SUPPORT_WATCHDOG_ENABLED',
       '{"regle":"À 1, le serveur écrit toutes les 2 minutes un fichier témoin avec son état (mémoire, disque, demandes en cours) et le supprime à l''arrêt normal. Si ce témoin est encore là au démarrage suivant, le logiciel en déduit un arrêt brutal et crée un incident avec la durée d''indisponibilité estimée et la cause probable. À 0, rien de cela n''est fait. Seule la valeur 0 désactive. La valeur n''est lue qu''au démarrage du serveur : un changement ne prend effet qu''au redémarrage suivant.","titre":"Détection d''un arrêt brutal du serveur","entetes":["Cas","Effet"],"cas":[["0","Aucun témoin, aucun relevé : un arrêt brutal n''est pas détecté."],["1, arrêt normal du logiciel","Le témoin est supprimé, aucun incident au redémarrage."],["1, arrêt brutal","Au redémarrage, un incident « Arrêt brutal du serveur » est créé avec la cause probable et les minutes d''indisponibilité."],["1, extinction normale de Windows","Pas d''incident ; l''arrêt reste seulement dans l''historique du serveur."],["1, simple mise à jour du logiciel sans arrêt du serveur","Pas d''incident."]],"rappels":["À 0, la boîte noire du Centre de Support indique qu''aucun relevé n''est enregistré.","Redémarrer le serveur après avoir changé la valeur."]}'
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM parametre_explication WHERE str_KEY = 'SUPPORT_WATCHDOG_ENABLED');

INSERT INTO parametre_explication (str_KEY, explication)
SELECT 'SUPPORT_AUTO_TICKET_ENABLED',
       '{"regle":"À 1, le logiciel ouvre de lui-même un ticket de support quand une erreur enregistrée est grave : tout de suite pour une erreur fatale, ou quand la même erreur s''est répétée un certain nombre de fois (5 par défaut, réglable par le seuil de répétitions, SUPPORT_AUTO_TICKET_SEUIL). À toute autre valeur, les erreurs restent enregistrées mais aucun ticket n''est ouvert. La valeur est relue à chaque erreur enregistrée.","titre":"Ouverture automatique d''un ticket","entetes":["Cas","Effet"],"cas":[["0","Aucun nouveau ticket automatique."],["1, erreur fatale","Un ticket « [Auto] » est créé dès la première fois."],["1, erreur répétée","Un ticket est créé quand le nombre de répétitions atteint le seuil (5 par défaut)."],["0 ou 1, ticket déjà ouvert pour la même erreur","L''erreur est rattachée à ce ticket, sans en créer un autre."]],"rappels":["L''e-mail envoyé au support pour ces tickets dépend du paramètre de notification du support (SUPPORT_NOTIFY_ENABLED).","Les tickets se consultent dans le Centre de Support."]}'
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM parametre_explication WHERE str_KEY = 'SUPPORT_AUTO_TICKET_ENABLED');

INSERT INTO parametre_explication (str_KEY, explication)
SELECT 'SUGGESTION_RESERVE_HOOK_VENTE',
       '{"regle":"À 1, après chaque vente validée, le logiciel regarde le stock du rayon des produits vendus qui sont gérés en réserve et les ajoute si besoin à une suggestion automatique de déplacement. À 0, les ventes ne génèrent plus ces suggestions ; le reste du module de réserve continue de fonctionner. Seules les valeurs 0, false ou non désactivent ; paramètre absent, le déclenchement est actif. La valeur est relue à chaque vente.","titre":"Suggestions de réserve après une vente","entetes":["Cas","Effet"],"cas":[["0","Aucune suggestion n''est créée à partir des ventes."],["1, stock du rayon au seuil mini ou en dessous","Le produit est ajouté à la suggestion automatique « réserve vers rayon »."],["1, stock du rayon au-dessus du seuil de réserve","Le produit est ajouté à la suggestion automatique « rayon vers réserve »."],["1, produit non géré en réserve ou sans seuil","Rien n''est proposé pour ce produit."]],"rappels":["Tous les produits d''un même ticket sont examinés ensemble, une fois la vente enregistrée ; la vente n''est jamais remise en cause.","Les suggestions créées à l''entrée en stock d''un bon de livraison ne dépendent pas de ce paramètre."]}'
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM parametre_explication WHERE str_KEY = 'SUGGESTION_RESERVE_HOOK_VENTE');

INSERT INTO parametre_explication (str_KEY, explication)
SELECT 'SUPPORT_DB_MONITOR_ENABLED',
       '{"regle":"À 1, le logiciel contrôle toutes les 5 minutes l''état de la base de données et des connexions du poste, et crée une alerte en cas de saturation ou de blocage. À toute autre valeur, ces contrôles ne font rien. La valeur est relue à chaque passage.","titre":"Ce qui est surveillé à 1","entetes":["Contrôle","Alerte"],"cas":[["Connexions ouvertes sur la base","Alerte après 3 mesures de suite au-dessus du seuil de connexions (80 % du maximum par défaut, SUPPORT_DB_CONN_PCT)."],["Requêtes en cours trop longues","Alerte au-delà de la durée fixée (10 secondes par défaut, SUPPORT_DB_SLOW_QUERY_S), avec la liste des requêtes."],["Attentes de verrou","Alerte selon le nombre d''attentes en cours (seuil de 5 par défaut, SUPPORT_DB_LOCK_WAITS)."],["Temps pour obtenir une connexion","Alerte après 2 mesures de suite au-dessus du délai toléré (2000 ms par défaut, SUPPORT_POOL_WAIT_MS)."],["Poste saturé ou connexions jamais rendues","Les fils de traitement occupés et les connexions inactives depuis longtemps sont aussi contrôlés."]],"rappels":["Au plus une alerte par indicateur et par jour.","Les alertes apparaissent dans le Centre de Support.","À 0, les mesures restent consultables à la demande dans le Centre de Support, mais plus aucune alerte n''est créée."]}'
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM parametre_explication WHERE str_KEY = 'SUPPORT_DB_MONITOR_ENABLED');

INSERT INTO parametre_explication (str_KEY, explication)
SELECT 'KEY_ETIQUETTE_ESPACE_H_MM',
       '{"regle":"Espace laissé entre deux colonnes d''étiquettes, en millimètres. Il n''est pris en compte que si la planche choisie est le modèle PERSONNALISE ; les autres modèles ont leur propre espace fixe. Valeur vide ou illisible : 0. Une valeur négative est ramenée à 0. La virgule et le point sont acceptés. La valeur est relue à chaque fabrication du PDF d''étiquettes.","titre":"Espace horizontal selon la planche","entetes":["Situation","Espace appliqué entre les colonnes"],"cas":[["Modèle PERSONNALISE, valeur 0 ou vide","0 mm : les étiquettes se touchent"],["Modèle PERSONNALISE, valeur 2,5","2,5 mm entre chaque colonne"],["Modèle PERSONNALISE, valeur -3","0 mm (valeur négative ignorée)"],["Planche 38,1 x 21,2","2,54 mm fixes, le paramètre n''est pas lu"],["Planches 38 x 21,2 et 38 x 21 arrondie","0 mm fixe, le paramètre n''est pas lu"]],"rappels":["Si les marges gauche et haut ne sont pas renseignées, la grille est centrée sur la page A4 : changer l''espace déplace donc aussi la première colonne.","L''espace est multiplié par l''échelle d''impression (paramètre d''échelle en %).","Dans Étiquettage Pro, l''écran de réglage accepte de 0 à 50 mm ; une valeur saisie dans l''aperçu prime sur ce paramètre pour l''impression en cours."]}'
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM parametre_explication WHERE str_KEY = 'KEY_ETIQUETTE_ESPACE_H_MM');

INSERT INTO parametre_explication (str_KEY, explication)
SELECT 'KEY_ETIQUETTE_ESPACE_V_MM',
       '{"regle":"Espace laissé entre deux rangées d''étiquettes, en millimètres. Il n''est pris en compte que si la planche choisie est le modèle PERSONNALISE ; sur les trois planches prédéfinies, l''espace vertical est toujours 0. Valeur vide ou illisible : 0. Une valeur négative est ramenée à 0. La valeur est relue à chaque fabrication du PDF d''étiquettes.","titre":"Espace vertical selon la planche","entetes":["Situation","Espace appliqué entre les rangées"],"cas":[["Modèle PERSONNALISE, valeur 0 ou vide","0 mm : les rangées se touchent"],["Modèle PERSONNALISE, valeur 1,5","1,5 mm entre chaque rangée"],["Modèle PERSONNALISE, valeur négative","0 mm (valeur négative ignorée)"],["Planches prédéfinies","0 mm fixe, le paramètre n''est pas lu"]],"rappels":["Si la marge haute n''est pas renseignée, la grille est centrée en hauteur sur la page A4 : changer l''espace déplace aussi la première rangée.","L''espace est multiplié par l''échelle d''impression (paramètre d''échelle en %).","Dans Étiquettage Pro, l''écran de réglage accepte de 0 à 50 mm ; une valeur saisie dans l''aperçu prime sur ce paramètre pour l''impression en cours."]}'
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM parametre_explication WHERE str_KEY = 'KEY_ETIQUETTE_ESPACE_V_MM');

INSERT INTO parametre_explication (str_KEY, explication)
SELECT 'KEY_ETIQUETTE_DECALAGE_X_MM',
       '{"regle":"Décale toute la planche d''étiquettes vers la droite (valeur positive) ou vers la gauche (valeur négative), en millimètres. Le décalage s''ajoute à la position de départ de la grille (marge gauche si elle est renseignée, sinon grille centrée). Il s''applique à tous les modèles de planche, pas seulement au modèle PERSONNALISE. Valeur vide ou illisible : 0. La valeur est relue à chaque fabrication du PDF.","titre":"Exemples de décalage horizontal","entetes":["Valeur","Effet sur la planche imprimée"],"cas":[["0 ou vide","Aucun décalage"],["1,5","Toutes les étiquettes sont imprimées 1,5 mm plus à droite"],["-2","Toutes les étiquettes sont imprimées 2 mm plus à gauche"],["abc","Valeur illisible : aucun décalage"]],"rappels":["Sert à corriger une imprimante qui imprime toujours un peu trop à gauche ou à droite : imprimer la page de test de calibrage, mesurer l''écart, saisir la correction.","Le décalage n''est pas multiplié par l''échelle d''impression.","L''écran de réglage d''Étiquettage Pro accepte de -50 à 50 mm ; le moteur d''impression lui-même n''applique aucune borne à une valeur saisie directement dans les paramètres."]}'
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM parametre_explication WHERE str_KEY = 'KEY_ETIQUETTE_DECALAGE_X_MM');

INSERT INTO parametre_explication (str_KEY, explication)
SELECT 'KEY_ETIQUETTE_DECALAGE_Y_MM',
       '{"regle":"Décale toute la planche d''étiquettes vers le bas (valeur positive) ou vers le haut (valeur négative), en millimètres. Le décalage s''ajoute à la position de départ de la grille (marge haute si elle est renseignée, sinon grille centrée en hauteur). Il s''applique à tous les modèles de planche. Valeur vide ou illisible : 0. La valeur est relue à chaque fabrication du PDF.","titre":"Exemples de décalage vertical","entetes":["Valeur","Effet sur la planche imprimée"],"cas":[["0 ou vide","Aucun décalage"],["2","Toutes les étiquettes sont imprimées 2 mm plus bas"],["-1,5","Toutes les étiquettes sont imprimées 1,5 mm plus haut"],["abc","Valeur illisible : aucun décalage"]],"rappels":["Sert à corriger une imprimante qui imprime toujours un peu trop haut ou trop bas : imprimer la page de test de calibrage, mesurer l''écart, saisir la correction.","Le décalage n''est pas multiplié par l''échelle d''impression.","L''écran de réglage d''Étiquettage Pro accepte de -50 à 50 mm ; le moteur d''impression lui-même n''applique aucune borne à une valeur saisie directement dans les paramètres."]}'
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM parametre_explication WHERE str_KEY = 'KEY_ETIQUETTE_DECALAGE_Y_MM');

INSERT INTO parametre_explication (str_KEY, explication)
SELECT 'KEY_ETIQUETTE_TELECHARGEMENT',
       '{"regle":"A 1, le PDF des étiquettes est envoyé comme un fichier à télécharger (etiquettes.pdf) : le navigateur l''enregistre et vous l''ouvrez avec le lecteur PDF du poste. A 0, ou toute autre valeur, le PDF s''affiche directement dans le navigateur. Le réglage vaut aussi pour la page de test de calibrage. La valeur est relue à chaque impression d''étiquettes.","titre":"Ouverture du PDF d''étiquettes","entetes":["Valeur","Effet"],"cas":[["0","Le PDF s''affiche dans le navigateur"],["1","Le PDF est téléchargé, à ouvrir avec le lecteur PDF du poste"],["vide ou autre valeur","Comme 0 : affichage dans le navigateur"]],"rappels":["Le téléchargement est utile quand l''impression depuis le navigateur change la taille des étiquettes : le lecteur PDF du poste garde ses réglages d''impression (taille réelle).","Seule la valeur 1 exactement active le téléchargement."]}'
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM parametre_explication WHERE str_KEY = 'KEY_ETIQUETTE_TELECHARGEMENT');

INSERT INTO parametre_explication (str_KEY, explication)
SELECT 'KEY_ETIQUETTE_CODE_PAR_PRODUIT',
       '{"regle":"A 1, chaque produit est imprimé avec le code de son propre type d''étiquette (code-barres, QR, DataMatrix...) ; un produit sans type à code garde le code par défaut des étiquettes. A 0, le même code, celui choisi par défaut ou dans l''aperçu, sert pour toute la planche. Seule la valeur 0 coupe le fonctionnement par produit : une valeur vide ou autre agit comme 1. La valeur est relue à chaque impression.","titre":"Code imprimé sur les étiquettes","entetes":["Valeur","Effet"],"cas":[["1","Chaque produit selon son type d''étiquette ; sans type, le code par défaut"],["0","Un seul code pour toute la planche"],["vide ou autre valeur","Comme 1"]],"rappels":["La case correspondante de l''aperçu avant impression d''Étiquettage Pro prime sur ce paramètre pour l''impression en cours.","Quand l''administrateur enregistre les réglages de l''aperçu comme réglages par défaut, ce paramètre est réécrit avec l''état de la case.","Le code par défaut des étiquettes se règle par un autre paramètre (code des étiquettes : CODE128, QR ou DATAMATRIX)."]}'
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM parametre_explication WHERE str_KEY = 'KEY_ETIQUETTE_CODE_PAR_PRODUIT');

INSERT INTO parametre_explication (str_KEY, explication)
SELECT 'ACCES_DEPANNAGE_ACTIF',
       '{"regle":"A 1, l''assistance peut ouvrir le compte système sans mot de passe, le temps d''une intervention. A 0, ou toute autre valeur, cet accès est fermé. La valeur est relue à chaque tentative de connexion. Rien ne referme l''accès automatiquement.","titre":"Etat de l''accès de dépannage","entetes":["Valeur","Effet"],"cas":[["0","Accès fermé (réglage normal)"],["1","L''assistance peut ouvrir le compte système sans mot de passe, le temps d''une intervention"],["vide ou autre valeur","Comme 0 : accès fermé"]],"rappels":["Remettre à 0 dès la fin de l''intervention : rien ne referme l''accès à votre place.","Un accès resté ouvert est signalé comme anomalie dans les contrôles du Centre de Support, à chaque démarrage et à chaque rejeu des contrôles.","Seul le super administrateur peut modifier ce paramètre ; chaque changement est inscrit au journal (sécurité et droits)."]}'
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM parametre_explication WHERE str_KEY = 'ACCES_DEPANNAGE_ACTIF');

INSERT INTO parametre_explication (str_KEY, explication)
SELECT 'KEY_VENTE_LECTURE_GS1',
       '{"regle":"A 1, quand on scanne à la vente une étiquette GS1 (QR ou DataMatrix), le logiciel retrouve le produit par son CIP, sinon par son code EAN, et lit aussi le lot et la date de péremption ; un lot périmé est signalé. A 0, l''étiquette 2D est quand même acceptée, mais seul le CIP (sinon l''EAN) en est tiré : le scan continue comme un code-barres classique, sans contrôle du lot, avec un message qui le rappelle. La valeur est relue à chaque ouverture de l''écran de vente.","titre":"Scan d''une étiquette 2D à la vente","entetes":["Valeur","Effet"],"cas":[["0","Seul le code du produit est lu ; message « CIP lu (sans contrôle du lot) »"],["1","Produit, lot et péremption sont lus ; le lot périmé est signalé"],["vide ou autre valeur","Comme 0"]],"rappels":["Après un changement, fermer puis rouvrir l''écran de vente pour qu''il soit pris en compte.","A 1, la conduite à tenir quand la boîte scannée n''est pas du lot que le logiciel sort dépend du paramètre de contrôle du lot GS1 (A = avertir, B = avertir et sortir le lot scanné, C = bloquer).","Les étiquettes étendues (DataMatrix+ et QR+) sont toujours refusées à la vente, quelle que soit la valeur."]}'
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM parametre_explication WHERE str_KEY = 'KEY_VENTE_LECTURE_GS1');

INSERT INTO parametre_explication (str_KEY, explication)
SELECT 'KEY_CONTROLE_ACHAT_DELAI_SAISIE_JOURS',
       '{"regle":"Nombre de jours accordés pour saisir un bon de livraison. Le délai d''un BL est la date de saisie moins la date du BL du grossiste, en jours : s''il est inférieur ou égal à cette valeur, le BL est compté « saisi dans le délai », au-delà il est « saisi en retard ». Paramètre absent ou illisible : 1 jour ; valeur négative : 0. La valeur est relue à chaque calcul du tableau de bord du contrôle des achats.","titre":"Exemple avec un délai de 1 jour","entetes":["BL du grossiste daté du","Saisi le","Ecart","Classement"],"cas":[["10/11","10/11","0 jour","Dans le délai"],["10/11","11/11","1 jour","Dans le délai"],["10/11","12/11","2 jours","En retard"],["Date du BL absente","12/11","inconnu","Délai inconnu, ni bon ni en retard"]],"rappels":["Le résultat se voit dans le tableau de bord du contrôle des achats : tuiles « Saisis dans le délai » et « Saisis en retard », par groupe de grossistes et par grossiste.","Le délai se modifie aussi depuis ce tableau de bord, entre 0 et 60 jours, par un utilisateur qui en a le droit.","A 0, seul un BL saisi le jour même de sa date est dans le délai."]}'
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM parametre_explication WHERE str_KEY = 'KEY_CONTROLE_ACHAT_DELAI_SAISIE_JOURS');

INSERT INTO parametre_explication (str_KEY, explication)
SELECT 'KEY_TICKET_LENT_SEUIL_MS',
       '{"regle":"Durée, en millisecondes, à partir de laquelle l''impression d''un ticket de vente est jugée lente. Une impression qui dure au moins cette valeur est signalée au Centre de Support (« Impression du ticket lente »), avec le détail du temps par étape et l''imprimante. Valeur vide ou illisible : 5000 ms, soit 5 secondes. Attention : à 0, toutes les impressions sont signalées. L''impression elle-même n''est jamais modifiée ni bloquée. La valeur est relue à chaque impression.","titre":"Effet selon la valeur","entetes":["Valeur","Effet"],"cas":[["5000","Signalement des tickets imprimés en 5 secondes ou plus"],["10000","Signalement à partir de 10 secondes"],["vide ou illisible","Comme 5000"],["0","Chaque impression de ticket est signalée, même rapide"]],"rappels":["Le signalement indique l''étape qui a retenu l''impression : recherche de l''imprimante, envoi à l''imprimante ou lecture de la vente.","Les signalements se consultent dans le Centre de Support, module Ticket."]}'
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM parametre_explication WHERE str_KEY = 'KEY_TICKET_LENT_SEUIL_MS');

INSERT INTO parametre_explication (str_KEY, explication)
SELECT 'KEY_JOURNAL_CONSERVATION_MOIS',
       '{"regle":"Nombre de mois pendant lesquels les lignes du journal sont gardées. A 0, valeur vide, négative ou illisible, rien n''est jamais supprimé. Au-dessus de 0, les lignes plus anciennes sont supprimées chaque nuit, à 3 h 27 ; par sécurité, le logiciel garde toujours au moins 3 mois, même si la valeur est 1 ou 2. La valeur est relue à chaque purge nocturne.","titre":"Durée réellement conservée","entetes":["Valeur","Effet"],"cas":[["0","Tout le journal est gardé, aucune purge"],["1 ou 2","Les 3 derniers mois sont gardés (minimum de sécurité)"],["6","Les 6 derniers mois sont gardés"],["12","Les 12 derniers mois sont gardés"]],"rappels":["La suppression est définitive : les lignes purgées ne peuvent plus être consultées dans le journal.","La purge n''a lieu que si le serveur est allumé à 3 h 27 ; aucun rattrapage au démarrage n''a été trouvé dans le code."]}'
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM parametre_explication WHERE str_KEY = 'KEY_JOURNAL_CONSERVATION_MOIS');

INSERT INTO parametre_explication (str_KEY, explication)
SELECT 'KEY_AVIS_ACTIF',
       '{"regle":"A 1, les clients peuvent déposer un avis depuis la page publique ouverte par le QR code de la pharmacie. A 0, la réception est suspendue : la page indique que la pharmacie ne reçoit pas d''avis pour le moment, et tout envoi est refusé sans être enregistré. Seule la valeur 0 suspend : une valeur vide ou autre agit comme 1. La valeur est relue à chaque ouverture de la page et à chaque envoi.","titre":"Réception des avis clients","entetes":["Valeur","Effet"],"cas":[["1","Les avis sont reçus et enregistrés"],["0","Message « La pharmacie ne reçoit pas d''avis pour le moment », rien n''est enregistré"],["vide ou autre valeur","Comme 1"]],"rappels":["Ce paramètre se règle aussi depuis l''écran de réglage des avis clients (case « actif »), qui le réécrit à l''enregistrement.","Suspendre ne supprime pas les avis déjà reçus et ne change pas le QR code.","Un lien dont le jeton n''est pas valide est refusé dans tous les cas, quelle que soit la valeur."]}'
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM parametre_explication WHERE str_KEY = 'KEY_AVIS_ACTIF');

INSERT INTO parametre_explication (str_KEY, explication)
SELECT 'KEY_ENTETES_X_USER_INFO',
       '{"regle":"À 0, le serveur ne reconnaît un utilisateur que par sa session ouverte : les anciens en-têtes qui annoncent l''utilisateur sans preuve sont ignorés. À 1, ces anciens en-têtes valent de nouveau connexion, pour une ancienne application qui en aurait encore besoin. La valeur est gardée une minute en mémoire : un changement prend effet au plus tard une minute après.","titre":"Anciens en-têtes de connexion","entetes":["Valeur","Effet"],"cas":[["0","Anciens en-têtes ignorés. Un appel sans session ouverte est refusé (déconnecté)."],["1","Anciens en-têtes de nouveau acceptés comme connexion (ancienne application)."],["Absent, illisible ou paramètre désactivé","Traité comme 0."]],"rappels":["Laisser à 0. Ne passer à 1 que sur demande du support, pour une ancienne application précise, et revenir à 0 dès que possible.","Seule la valeur 1 active l''option ; toute autre valeur vaut 0."]}'
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM parametre_explication WHERE str_KEY = 'KEY_ENTETES_X_USER_INFO');

INSERT INTO parametre_explication (str_KEY, explication)
SELECT 'KEY_CONNEXION_BADGE',
       '{"regle":"À 1, un employé peut ouvrir sa session en présentant le QR code de son badge. À 0, toute connexion par badge est refusée ; la connexion par identifiant et mot de passe ne change pas. La valeur est relue à chaque présentation de badge.","titre":"Connexion par badge","entetes":["Valeur","Effet"],"cas":[["1","Badge accepté s''il est reconnu et rattaché à un utilisateur actif."],["0","Badge toujours refusé, même valide."],["Absent ou autre valeur","Connexion par badge permise : seule la valeur 0 la coupe."]],"rappels":["Le code PIN après le badge dépend d''un autre paramètre (KEY_CONNEXION_BADGE_PIN).","Les essais ratés sont comptés : après plusieurs échecs, une attente est imposée.","Chaque connexion par badge est notée au journal avec la mention « par badge »."]}'
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM parametre_explication WHERE str_KEY = 'KEY_CONNEXION_BADGE');

INSERT INTO parametre_explication (str_KEY, explication)
SELECT 'KEY_CONNEXION_BADGE_PIN',
       '{"regle":"À 1, après un badge reconnu, le logiciel demande le code PIN à 4 chiffres de l''employé avant d''ouvrir la session : une photo du badge ne suffit plus. À 0, le badge seul ouvre la session. La valeur est relue à chaque connexion par badge.","titre":"Code PIN après le badge","entetes":["Situation (paramètre à 1)","Effet"],"cas":[["Code jamais défini par l''employé","Pas de session : l''employé doit d''abord définir son code."],["Code non encore tapé","Pas de session : le logiciel demande « Tapez votre code PIN »."],["Code faux","Refus « Code PIN incorrect », compté comme un essai raté."],["Code juste","Session ouverte, notée au journal « par badge et code PIN »."],["Paramètre à 0, absent ou autre valeur","Le badge seul suffit."]],"rappels":["Avant de passer à 1, demander à chaque employé de définir son code dans « Mon compte », sinon il ne pourra plus entrer par badge.","Le code compte exactement 4 chiffres ; quatre chiffres identiques ou une suite (1234, 4321) sont refusés.","Sans effet si la connexion par badge est coupée (KEY_CONNEXION_BADGE à 0)."]}'
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM parametre_explication WHERE str_KEY = 'KEY_CONNEXION_BADGE_PIN');

INSERT INTO parametre_explication (str_KEY, explication)
SELECT 'KEY_EMPREINTES_PARTAGEES',
       '{"regle":"À 1, les empreintes digitales des employés peuvent être enregistrées sur le serveur et relues par les terminaux et bornes de pointage : une empreinte prise sur un appareil sert sur les autres. À 0, l''enregistrement et la lecture sont refusés (« Empreintes partagées désactivées »). La valeur est relue à chaque demande.","titre":"Empreintes partagées","entetes":["Valeur","Effet"],"cas":[["1","Enregistrement accepté pour un employé actif, avec consentement écrit obligatoire (date et personne). Lecture ouverte aux appareils de pointage."],["0","Enregistrement et lecture refusés. La suppression des empreintes d''un employé reste possible."],["Absent ou autre valeur","Traité comme 0."]],"rappels":["Donnée biométrique : n''activer qu''avec le consentement écrit de chaque employé.","Les empreintes sont gardées chiffrées dans la base : protéger les sauvegardes de la base comme la base elle-même.","Chaque enregistrement, lecture et suppression est tracé ; les empreintes des employés qui ne sont plus actifs sont effacées."]}'
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM parametre_explication WHERE str_KEY = 'KEY_EMPREINTES_PARTAGEES');

INSERT INTO parametre_explication (str_KEY, explication)
SELECT 'KEY_BORNE_POINTAGE_RESEAU_LOCAL',
       '{"regle":"À 1, une borne de pointage n''est écoutée que si son appel vient du réseau de l''officine ; depuis l''extérieur, elle reçoit le refus « Borne de pointage acceptée seulement sur le réseau de l''officine ». À 0, une borne enregistrée peut aussi pointer depuis Internet. La valeur est relue à chaque appel d''une borne.","titre":"Bornes de pointage : réseau accepté","entetes":["Valeur","Effet"],"cas":[["1","Appels acceptés seulement depuis le réseau de l''officine."],["0","Appels acceptés aussi depuis l''extérieur ; les autres contrôles de la borne restent appliqués."],["Absent, illisible ou autre valeur","Traité comme 1 : seule la valeur 0 ouvre l''accès extérieur."]],"rappels":["Laisser à 1 sauf besoin réel d''une borne hors de l''officine.","Dans tous les cas, la borne doit avoir été enregistrée par un administrateur et ne pas avoir été retirée."]}'
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM parametre_explication WHERE str_KEY = 'KEY_BORNE_POINTAGE_RESEAU_LOCAL');

INSERT INTO parametre_explication (str_KEY, explication)
SELECT 'KEY_PRIX_REF_CAISSE',
       '{"regle":"À 1, en vente assurance, la grille de vente montre pour chaque tiers-payant de la vente deux colonnes, prix de référence et taux, que le vendeur peut saisir ligne par ligne. La saisie reste sur la vente et sert aussitôt au calcul ; elle n''est écrite sur la fiche article, et notée au journal, qu''à la clôture de la vente. À 0, ces colonnes n''existent pas et le serveur refuse toute saisie de ce type. La valeur est relue à chaque ouverture de l''écran de vente.","titre":"Saisie du prix de référence à la caisse","entetes":["Cas","Effet"],"cas":[["0","Grille de vente inchangée, aucune colonne par tiers-payant, saisie refusée par le serveur."],["1, vente assurance","Colonnes prix de référence et taux par tiers-payant ; Entrée valide, Échap annule."],["1, vente au comptant","Aucune colonne : la saisie n''existe qu''en vente assurance."],["Bornes de la saisie","Prix de référence : entier, de 5 au prix de vente de la ligne. Taux : entier, de 5 à 100."],["Vente déjà clôturée","Saisie refusée."]],"rappels":["Une saisie validée à la clôture modifie la fiche article pour les ventes suivantes : vérifier la valeur avant de valider.","Sous la grille, une légende rappelle les couleurs : gris italique = valeur par défaut non enregistrée, violet = référence de la fiche ou saisie sur cette vente.","La base de calcul utilisée quand il y a plusieurs tiers-payants dépend de KEY_PRIX_REF_BASE_PAR_TP."]}'
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM parametre_explication WHERE str_KEY = 'KEY_PRIX_REF_CAISSE');

INSERT INTO parametre_explication (str_KEY, explication)
SELECT 'KEY_LIGNE_COMPTANT_VO',
       '{"regle":"À 1, la grille d''une vente assurance porte une colonne « C » : une ligne cochée sort du calcul des tiers-payants et, à la clôture, les lignes cochées forment une vente au comptant liée, avec son propre ticket. À 1 également, le ticket assurance imprime sous les produits concernés une ligne « taux : part » par tiers-payant. À 0, pas de colonne, cochage refusé par le serveur, clôture et ticket inchangés. La valeur est relue à chaque ouverture de l''écran de vente, et par le serveur à chaque cochage, calcul, clôture et impression.","titre":"Ligne au comptant dans une vente assurance","entetes":["Cas","Effet"],"cas":[["0","Aucune colonne « C », une seule vente, ticket assurance sans ligne de taux sous les produits."],["1, quelques lignes cochées","Une saisie, deux ventes, deux tickets : la vente assurance et la vente comptant liée."],["1, toutes les lignes cochées","Clôture refusée : passer la vente au comptant ou décocher au moins une ligne."],["1, ligne en promotion","Cochage refusé : une ligne au comptant ne porte pas de promotion."],["1, vente au comptant ou vente close","Colonne masquée ou cochage refusé : la coche n''existe qu''en vente assurance modifiable."]],"rappels":["Ce paramètre commande aussi les lignes « taux : part » du ticket assurance, même si personne ne coche de ligne.","Sur le ticket, rien n''est imprimé sous un produit qui suit simplement le taux de l''assurance, et un tiers-payant dont la part est nulle n''est pas imprimé."]}'
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM parametre_explication WHERE str_KEY = 'KEY_LIGNE_COMPTANT_VO');

INSERT INTO parametre_explication (str_KEY, explication)
SELECT 'KEY_SAUVEGARDE_ACTIVE',
       '{"regle":"À 1, le serveur sauvegarde la base toute seule chaque heure, et alerte le Centre de support si aucune sauvegarde n''a réussi depuis plus de 2 heures. À 0, plus de sauvegarde automatique et plus d''alerte d''ancienneté ; la sauvegarde lancée à la main reste possible. La valeur est relue chaque heure, au moment de sauvegarder.","titre":"Sauvegarde automatique de la base","entetes":["Valeur","Effet"],"cas":[["1","Une sauvegarde par heure, sans bloquer les ventes ; copie sur un second dossier si un dossier de copie est renseigné."],["0","Aucune sauvegarde automatique, aucune alerte « sauvegarde ancienne ». Sauvegarde manuelle seulement."],["Absent ou autre valeur","Traité comme 1 : seule la valeur 0 coupe la sauvegarde automatique."]],"rappels":["À 0, l''officine n''est protégée que par les sauvegardes lancées à la main : en cas de panne, tout ce qui a été saisi depuis la dernière est perdu.","Ce réglage se change aussi dans l''écran des sauvegardes (Centre de support, Stabilité du serveur, Sauvegardes), avec le dossier et les durées de conservation.","Par défaut, toutes les sauvegardes sont gardées 48 heures, puis une par jour pendant 30 jours."]}'
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM parametre_explication WHERE str_KEY = 'KEY_SAUVEGARDE_ACTIVE');

INSERT INTO parametre_explication (str_KEY, explication)
SELECT 'KEY_PRIX_REF_BASE_PAR_TP',
       '{"regle":"À 0, quand une vente assurance a plusieurs tiers-payants, toutes les parts sont calculées sur la même base : le plus petit des prix de référence de la ligne. À 1, chaque tiers-payant est calculé sur son propre prix de référence (ou sur le prix de vente s''il n''en a pas), multiplié par la quantité, avec son propre taux, dans l''ordre de priorité ; une part ne dépasse jamais ce qui reste du prix de la ligne. Les plafonds et la part du client se calculent ensuite comme avant. La valeur est relue à chaque calcul de la vente.","titre":"Exemple : ligne à 5 000, assurance A prioritaire à 70 %, assurance B à 20 %","entetes":["Valeur","Prix de référence","Part A","Part B","Part client"],"cas":[["0","A 4 000, B 3 000 (base commune 3 000)","2 100","600","2 300"],["1","A 4 000, B 3 000 (chacun sa base)","2 800","600","1 600"],["0","B 3 000 seulement (base commune 3 000)","2 100","600","2 300"],["1","B 3 000 seulement (A sur le prix de vente 5 000)","3 500","600","900"]],"rappels":["Ce choix change les montants facturés aux organismes et la part du client : à décider avec les règles de vos conventions.","À 0, un rappel de la règle du minimum s''affiche sous la grille de vente ; à 1, il disparaît (visible seulement si KEY_PRIX_REF_CAISSE vaut 1).","Sur une ligne marquée en prise en charge totale, chaque organisme est calculé sur sa propre base quelle que soit la valeur de ce paramètre."]}'
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM parametre_explication WHERE str_KEY = 'KEY_PRIX_REF_BASE_PAR_TP');

INSERT INTO parametre_explication (str_KEY, explication)
SELECT 'KEY_NETTOYER_SUGGESTION_OUVERTURE',
       '{"regle":"À 1, à chaque ouverture d''une suggestion de réapprovisionnement, le logiciel la nettoie avec la même règle que le bouton de nettoyage : les produits dont le stock ne justifie plus la commande au regard de leur seuil sortent de la suggestion. À 0, rien n''est retiré à l''ouverture ; le nettoyage ne se fait que par le bouton. La valeur est relue à chaque ouverture.","titre":"Nettoyage de la suggestion à l''ouverture","entetes":["Valeur","Effet"],"cas":[["0","La suggestion s''ouvre telle quelle. Nettoyage par le bouton seulement."],["1, des produits à retirer","Produits retirés avant l''affichage ; un message indique combien (« 3 produits retirés à l''ouverture »)."],["1, rien à retirer","La suggestion s''ouvre sans message."],["Absent ou autre valeur","Traité comme 0."]],"rappels":["Le stock comparé au seuil est celui du rayon, plus la réserve quand le produit y est géré, sur l''emplacement de l''utilisateur.","Chaque retrait est noté : la liste se retrouve dans « Produits retirés »."]}'
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM parametre_explication WHERE str_KEY = 'KEY_NETTOYER_SUGGESTION_OUVERTURE');

INSERT INTO parametre_explication (str_KEY, explication)
SELECT 'KEY_CORRESPONDANCE_SEUIL_ECART_PRIX',
       '{"regle":"C''est un montant en FCFA, entier, 0 par défaut. Le logiciel compare le dernier prix public TTC lu chez le grossiste au prix de vente de Prestige ; l''écart est signalé seulement s''il dépasse ce montant, en plus comme en moins. À 0, tout écart, même de 1 FCFA, est signalé. Un nombre négatif ou une valeur illisible vaut 0 ; aucune borne haute n''est imposée. La valeur est relue à chaque affichage des écarts.","titre":"Exemples","entetes":["Seuil","Prix grossiste / prix Prestige","Résultat"],"cas":[["0","2 005 / 2 000 (écart 5)","Signalé"],["50","2 050 / 2 000 (écart 50)","Non signalé : l''écart doit dépasser le seuil"],["50","2 051 / 2 000 (écart 51)","Signalé"],["50","1 900 / 2 000 (écart -100)","Signalé : l''écart compte dans les deux sens"]],"rappels":["Le résultat se voit dans Correspondance grossistes, vue « Écarts de prix publics » (les plus grands écarts d''abord) et sur la fiche des prix d''un produit.","Le seuil se règle aussi depuis cet écran, avec le droit nécessaire.","Seuls les prix publics TTC sont comparés ; un produit sans prix de vente ou sans prix public TTC n''est pas comparé."]}'
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM parametre_explication WHERE str_KEY = 'KEY_CORRESPONDANCE_SEUIL_ECART_PRIX');

INSERT INTO parametre_explication (str_KEY, explication)
SELECT 'KEY_AFFICHER_STOCK_GROSSISTE',
       '{"regle":"À 1, l''écran des suggestions affiche une colonne « STOCK » du grossiste, avec la disponibilité lue sur son extranet, quand le grossiste de la suggestion est lié à un extranet. À 0, la colonne est masquée et le serveur n''envoie pas cette information. La valeur est relue à chaque chargement des lignes de la suggestion.","titre":"Stock du grossiste dans les suggestions","entetes":["Cas","Effet"],"cas":[["0","Colonne du stock grossiste masquée. Les unités gratuites et les commandes en cours chez le grossiste restent affichées."],["1, grossiste lié à un extranet","Colonne « STOCK » suivie du nom du grossiste ; une valeur dans la cellule, toutes au survol."],["1, grossiste sans extranet lié","Aucune colonne d''extranet, donc pas de stock."],["Absent ou autre valeur","Traité comme 0."]],"rappels":["Le stock affiché est celui de la dernière lecture complète de l''extranet gardée en base, pas une interrogation en direct : il peut dater.","Tous les extranets ne donnent pas de disponibilité : la cellule reste vide quand le grossiste n''en publie pas pour le produit."]}'
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM parametre_explication WHERE str_KEY = 'KEY_AFFICHER_STOCK_GROSSISTE');
